class Solution {
public:
    int guessMajority(ArrayReader& reader) {
        int n = reader.length();
        int base = reader.query(0, 1, 2, 3);
        int reference = reader.query(1, 2, 3, 4);
        int compare = reader.query(0, 2, 3, 4);
        int same = 1;
        int different = 0;
        int differentIndex = -1;

        // For i >= 4, equality of the query scores means arr[i] == arr[0].
        for (int i = 4; i < n; ++i) {
            int current = reader.query(1, 2, 3, i);
            if (current == base) {
                ++same;
            } else {
                ++different;
                differentIndex = i;
            }
        }
        // Compare indices 1, 2, and 3 against index 0.
        // The overlapping queries expose equality through their scores.
        int q1 = reader.query(0, 1, 3, 4);
        int q2 = reader.query(0, 1, 2, 4);
        int score[3] = {compare, q1, q2};
        for (int i = 0; i < 3; ++i) {
            int index = i + 1;
            if (score[i] == reference) {
                ++same;
            } else {
                ++different;
                differentIndex = index;
            }
        }
        if (same == different) {
            return -1;
        }
        return same > different ? 0 : differentIndex;
    }
};
